package com.oms.order.service;

import org.junit.jupiter.api.*;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.RefundValues.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class RefundDispositionServiceTest {
    Map<String,Object> task(){return m("id",1,"order_line_id",10,"platform_oid","OID","sku_sn","A","goods_name","商品A","stock_unit","件","quantity",2,"state","DONE","cutoff_id",7,"command_json",m("request_id","CF_TEST","mode","REDUCE","demands",Collections.singletonList(m("platform_oid","OID","sku_sn","A","quantity",2))));}
    Map<String,Object> receipt(){return m("request_id","CF_TEST","state","COMPLETED","mode","REDUCE","quantity",2,"recorded_at","2026-10-24 10:00:00");}
    Map<String,Object> result(Map<String,Object> t,Map<String,Object> receipt){return RefundDispositionService.cancelResult(t,receipt,Collections.emptyList(),Collections.emptyList());}
    @Test void completedTaskAloneDoesNotProveCancellationOrStockRelease(){Map<String,Object> r=result(task(),null);assertNull(r.get("canceled_quantity"));assertNull(r.get("logical_released_quantity"));assertEquals(false,r.get("receipt_confirmed"));}
    @Test void olderReceiptProvesDemandCancellationButDoesNotInventReleasedReservation(){Map<String,Object> r=result(task(),receipt());assertEquals(2,r.get("canceled_quantity"));assertNull(r.get("logical_released_quantity"));}
    @Test void newReceiptShowsActualReleasedReservationIncludingZero(){Map<String,Object> receipt=receipt();receipt.putAll(m("effect_schema_version",1,"stock_effects",Collections.singletonList(m("sku_sn","A","logical_reservation_released",0))));Map<String,Object> r=result(task(),receipt);assertEquals(0L,r.get("logical_released_quantity"));}
    @Test void anotherRequestOrWrongQuantityCannotBeUsedAsThisRefundEvidence(){Map<String,Object> receipt=receipt();receipt.put("request_id","CF_OTHER");assertNull(result(task(),receipt).get("canceled_quantity"));receipt=receipt();receipt.put("quantity",3);assertNull(result(task(),receipt).get("canceled_quantity"));}
    @Test void stoppedOldTaskIsNeverCountedAsSuccessfullyCanceled(){Map<String,Object> t=task();t.put("state","CANCELED");assertFalse((Boolean)result(t,receipt()).get("receipt_confirmed"));assertNull(result(t,receipt()).get("canceled_quantity"));}
    @Test void sharedShipmentKeepsWholeWithdrawalSeparateFromRefundCancellation(){Map<String,Object> item=m("cutoff_id",7,"shipment_id",20,"warehouse_state","CONFIRMED","state","COMPLETED","stock_request",m("request_id","CF_W","mode","REPLAN","allocations",Arrays.asList(m("allocation_id",100,"quantity",2),m("allocation_id",200,"quantity",3))),"stock_receipt",m("state","COMPLETED","requests",Collections.singletonList(m("request_id","CF_W","mode","REPLAN","state","COMPLETED","quantity",5))));List<Map<String,Object>> sources=Arrays.asList(m("shipment_id",20,"allocation_id",100,"order_line_id",10,"sku_sn","A","stock_unit","件"),m("shipment_id",20,"allocation_id",200,"order_line_id",11,"sku_sn","B","stock_unit","件"));Map<String,Object> r=RefundDispositionService.cancelResult(task(),receipt(),Collections.singletonList(item),sources);Map<String,Object> w=RefundDispositionService.rows(r.get("warehouses")).get(0);assertEquals(2,r.get("canceled_quantity"));assertEquals(1,RefundDispositionService.rows(w.get("scope")).size());assertEquals(2,RefundDispositionService.rows(w.get("whole_scope")).size());assertEquals(true,w.get("stock_receipt_confirmed"));}
    @Test void returnUsesOwnPlanQuantitiesAndPreservesPendingAllocationOutsideThem(){Map<String,Object> p=m("id",9,"sku_sn","A","gift_plan_id",1,"quantity",2,"accepted_quantity",1,"posted_quantity",0,"waived_quantity",0,"result_json",m("warehouse_quantity",100,"parcel_pending_count",1,"lines",Collections.singletonList(m("good_qty",1,"bad_qty",0,"posted",0))));Map<String,Object> r=RefundDispositionService.returnResult(p,null);assertEquals("GIFT",r.get("item_kind"));assertEquals(1L,r.get("accepted_quantity"));assertEquals(0L,r.get("posted_quantity"));assertEquals(1L,r.get("remaining_quantity"));assertEquals(1L,r.get("unposted_quantity"));assertEquals(true,r.get("parcel_pending"));}
    @Test void waivedGoodsAreNotTreatedAsActuallyReceived(){Map<String,Object> r=RefundDispositionService.returnResult(m("quantity",3,"accepted_quantity",1,"posted_quantity",1,"waived_quantity",2),null);assertEquals(0L,r.get("remaining_quantity"));assertEquals(1L,r.get("accepted_quantity"));assertEquals(2L,r.get("waived_quantity"));}
    @Test void readsValidateTenantBeforeCallingInventory(){RefundDispositionService service=new RefundDispositionService();service.refunds=mock(RefundService.class);service.inventory=mock(OrderWarehouseClient.class);when(service.refunds.business("OTHER",9,false)).thenThrow(new IllegalArgumentException("无权访问"));assertThrows(IllegalArgumentException.class,()->service.report("OTHER",9));verifyNoInteractions(service.inventory);}
}
